{
  "info": {
    "title": "Ozone Connect - Bank Products Data",
    "contact": {
      "name": "Ozone Financial Technology Limited"
    },
    "description": "This document provides an API description in [OpenAPI](https://spec.openapis.org/oas/v3.0.1.html)\nfor Bank Product Data APIs for Ozone Connect.\n\nThese APIs should be implemented by an financial institution so that Ozone\ncan expose the API operations to TPPs.\n\n#### Implementer Notes\n\nImplementers should note that this API prescribes a positive response for correctly executed\noperations including those where no data is returned. This is consistent with the general principles\nof REST.\n\nPlease refer to the API Hub documentation for details of test cases that are \navailable for this API using the Ozone Connect test suite.\n\n### Versioning\n\nThe `version` property implements the following pattern `{standards-major}.{standards-minor}.{ozone-connect-version}`, where:\n\n* `standards-major` is the major version of the latest UAE standard that the API description implements.\n* `standards-minor` is the minor version of the latest UAE standard that the API description implements.\n* `ozone-connect-version` is the version of the Ozone Connect API description.\n\nSo, for example, `v2.0.1` indicates the first version of the Ozone Connect API description that implements the UAE standard version 2.0.\n### v2.1.2\n* Added `DenominationCurrency` to `get /products` operation.\n* Added new enumeration values to `FinanceDetails.Type`.\n### v2.1.1\n* Changed loan to finance for all Schema Objects names and object descriptions.\n* Changed pagination approach to adopt standardised parameters for open finance.\n* Changed `ProductCategories` to mandatory in `post /leads` request.\n* Changed `ProductCategories` from array of objects to array of strings.\n* Changed `Fees` to `Charges` for all product types.\n* Changed `Charges` structure to match Extended Product Data requirements.\n* Changed name of objects and descriptions to use \"Sharia\" consistently throughout.\n",
    "version": "v2.1.2"
  },
  "servers": [
    {
      "url": "https://[Ozone_Connect_API]"
    }
  ],
  "source_path": "/leads",
  "operations": {
    "post": {
      "tags": [
        "Leads"
      ],
      "summary": "Create a Lead",
      "description": "Create a Lead\n",
      "operationId": "CreateLead",
      "parameters": [
        {
          "$ref": "#/components/parameters/providerId"
        },
        {
          "$ref": "#/components/parameters/callerOrgId"
        },
        {
          "$ref": "#/components/parameters/callerClientId"
        },
        {
          "$ref": "#/components/parameters/callerSoftwareStatementId"
        },
        {
          "$ref": "#/components/parameters/apiUri"
        },
        {
          "$ref": "#/components/parameters/apiOperation"
        },
        {
          "$ref": "#/components/parameters/callerInteractionId"
        },
        {
          "$ref": "#/components/parameters/ozoneInteractionId"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        }
      ],
      "requestBody": {
        "description": "Request Body\n",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/LeadRequest"
            }
          }
        }
      },
      "responses": {
        "201": {
          "$ref": "#/components/responses/201LeadResponse"
        },
        "400": {
          "$ref": "#/components/responses/BadRequestResponse"
        },
        "401": {
          "$ref": "#/components/responses/NotAuthorizedResponse"
        },
        "403": {
          "$ref": "#/components/responses/ForbiddenResponse"
        },
        "500": {
          "$ref": "#/components/responses/InternalServerErrorResponse"
        },
        "default": {
          "$ref": "#/components/responses/errorResponse"
        }
      }
    }
  },
  "security": [
    {},
    {
      "OzoneConnectApiKey": []
    },
    {
      "OzoneConnectClientCredentials": [
        "placeholder"
      ]
    },
    {
      "OzoneConnectJwtAuth": []
    }
  ],
  "securitySchemes": {
    "OzoneConnectApiKey": {
      "description": "Communications between the API Hub and the LFI Ozone Connect implementation are secured using an API Key, which is a secret shared between the API Hub and the LFI.",
      "type": "apiKey",
      "in": "header",
      "name": "Authorization"
    },
    "OzoneConnectClientCredentials": {
      "type": "oauth2",
      "description": "Communications between the API Hub and the LFI Ozone Connect implementation are secured using a Client Credentials grant type.\n\nLFIs must host an OAuth 2.0 Authorization Server to utilise this security pattern. Scope values are set during the onboarding process, and represented by a placeholder in this API description.\n",
      "flows": {
        "clientCredentials": {
          "tokenUrl": "https://example.lfi.ae/token",
          "scopes": {
            "placeholder": "Placeholder for scopes, which are set by the LFI during onboarding"
          }
        }
      }
    },
    "OzoneConnectJwtAuth": {
      "description": "Communications between the API Hub and the LFI Ozone Connect implementation are secured using the \"JWT Auth\" mechanism, where the Client presents a signed JSON Web Token as a credential.\n\nThe Server MUST verify the signature in order to authenticate the Client.\n\nPlease note that the value of the `scheme` parameter is not a registered HTTP Authentication Scheme, to indicate it is specific to Ozone Connect. Please refer to API Hub documentation for further details.\n",
      "type": "http",
      "scheme": "Ozone-Connect-JWT-Auth"
    }
  }
}

